const existingArticles = [
  {
    collection: 'docs', slug: 'getting-started', category: 'Start here',
    title: 'Get started with Cap Table',
    description: 'Open Cap Table, explore the sample company, and set up your first company with share classes, stakeholders, and securities.',
    summary: 'Set up your company or explore the app with sample data.',
    related: ['navigation-and-shortcuts', 'company-profile-and-currency', 'what-is-a-cap-table'],
    sections: [
      section('open-the-app', 'Open the app', `<p>Cap Table is free cap table software for maintaining ownership records, tracking equity awards, and modeling funding rounds. This website contains the app, product documentation, and guides.</p><p><a href="${APP_URL}">Open Cap Table</a>, choose <strong>Get started now</strong>, and sign in or create a Puter account when prompted. If you are already signed in, the app opens directly. Your company records and supporting attachments are stored in your own Puter account. You need an internet connection for cloud reads and saves.</p>`),
      section('explore-sample-data', 'Explore with sample data', `<p>On the welcome screen, select <strong>Explore with sample data</strong> to load a fictional company. The sample includes founder shares, investors, option grants, and a draft funding scenario. The banner identifies the records as sample data.</p><p>Use this workspace to inspect the Home dashboard, open the Cap table view, and explore Round modeling. When you are ready to remove the sample records, use <strong>Start fresh</strong> in the sample banner and review the confirmation. Export anything you want to retain before clearing it.</p><figure class="site-figure"><img src="/screenshots/cap-table-desktop.png" width="1440" height="960" loading="lazy" decoding="async" alt="Cap Table Home dashboard with the fictional Acme Robotics sample company" /><figcaption>The Home dashboard with the app’s fictional sample company.</figcaption></figure>`),
      section('set-up-your-company', 'Set up your own company', `<p>Choose <strong>Set up my company</strong> on the welcome screen if you want to start with your own records. Enter the company details requested by the setup form. Use dates and quantities from the company’s records rather than estimates. If you enter an authorized common-share count during setup, the app creates a Common Stock class. Review that class before adding another one.</p><p>The company selector lets you switch between companies. Check the selected company before making changes or importing a file. Each company has its own records.</p>`),
      section('add-records', 'Add records in a useful order', `<ol><li><strong>Share classes.</strong> Define common and preferred classes before recording shares against them. Authorized shares are the class limit, not the quantity already issued.</li><li><strong>Stakeholders.</strong> Add the people and entities that hold securities.</li><li><strong>Equity plans.</strong> Set up a plan before recording options or RSUs that draw from its reserve.</li><li><strong>Securities.</strong> Record issued shares, grants, and convertible instruments with the appropriate holder, dates, and terms.</li></ol><p>If the records already exist in a spreadsheet, follow <a href="/docs/importing-a-cap-table/">Import a cap table from CSV</a> instead of entering every row manually.</p>`),
      section('check-your-first-cap-table', 'Check your first cap table', `<p>Open <strong>Cap table</strong> and compare the results with your source records. Review the outstanding and fully diluted views, the option-pool setting, and the as-of date. These choices affect the denominator used for ownership percentages.</p><p>Check the total shares, each holder’s securities, and any convertible agreements. In this app, SAFEs and convertible notes do not enter the ownership share counts until they convert. Use <strong>Needs attention</strong> to review records that may require an action, such as an expired grant or an outdated recorded valuation.</p><p>Once the records reconcile, export a company backup from Settings. See <a href="/docs/exports-and-history/">Exports, backups, and history</a> for the differences between a report, a backup, and a restore point.</p>`),
    ],
  },
  {
    collection: 'docs', slug: 'importing-a-cap-table', category: 'Maintain your records',
    title: 'Import a cap table from CSV',
    description: 'Import stakeholders and securities into Cap Table, map spreadsheet columns, check equity plan assignments, and review the preview before saving.',
    summary: 'Prepare your files, match columns, and review the import preview.',
    related: ['cap-table-maintenance-checklist', 'managing-equity-plans', 'exports-and-history'],
    sections: [
      section('prepare-your-files', 'Prepare your files', `<p>The CSV importer adds stakeholders or securities to the selected company. It does not replace the whole cap table. Start from the importer’s <strong>Stakeholders template</strong> or <strong>Securities template</strong> to see the supported columns.</p><p>Use separate files for stakeholders and securities. Securities identify their holders by name, so import stakeholders first and keep names consistent across the files. Use explicit dates, such as <code>2026-09-09</code>, and check that quantities and prices occupy separate columns.</p><p>The importer accepts files up to 10 MiB and 10,000 parsed rows. Export a company backup first if you are adding records to an existing cap table.</p>`),
      section('choose-and-map', 'Choose a file and match its columns', `<ol><li>Open <strong>Settings</strong> and choose <strong>Import from CSV</strong>.</li><li>Select whether the file contains <strong>Stakeholders</strong> or <strong>Securities</strong>.</li><li>Choose the CSV file. Review the automatic column matches.</li><li>Map any remaining required columns. Leave optional fields as <strong>Not in this file</strong> when appropriate.</li><li>Select <strong>Preview import</strong>.</li></ol><p>The preview is a review step. No imported records have been saved at this point. If a column is mapped incorrectly, go back and change the mapping before importing.</p>`),
      section('assign-equity-plans', 'Assign options and RSUs to a plan', `<p>The optional <strong>Plan</strong> column identifies the equity plan for an option or RSU award. Create the relevant plans before importing the awards.</p><ul><li>Use the plan’s name to assign the award to that plan.</li><li>Use <code>none</code> for an award outside every plan.</li><li>A blank value can be resolved when exactly one plan is eligible for the award. If several plans could hold it, specify the plan.</li></ul><p>Eligibility depends on the award type and the plan’s dates. The Plan field is not used for shares, warrants, SAFEs, or notes. Read <a href="/docs/managing-equity-plans/">Manage equity incentive plans</a> for how reserves and award assignments work.</p>`),
      section('review-the-preview', 'Review warnings and proposed records', `<p>Read the creation count, skipped stakeholders, proposed share classes, and rows with problems. Rows with validation problems will not be imported. If the preview proposes creating missing share classes, confirm that those classes and their names are intentional.</p><div class="site-note"><strong>Repeated securities are not automatically skipped.</strong><p>The preview warns when a row matches an existing security by holder, type, amount, and date. Importing that row again creates another security. Check the warning before importing the same file twice.</p></div><p>Existing stakeholders and repeated stakeholder names in the same file are handled separately from securities. Review the skip reasons rather than assuming every source row will create a record.</p>`),
      section('verify-the-result', 'Import and reconcile the result', `<p>Choose the import button after reviewing the preview. Then compare the resulting stakeholder list, securities, and cap table totals with the source file. Repeat the workflow for securities after importing stakeholders.</p><p>Imported awards can reveal an overcommitted equity plan. The app preserves the imported history and shows the shortfall; it does not make the underlying reserve larger simply to fit the file.</p><p>An import into a company that already has data takes a restore point first. A first import into an empty company may have no prior data to snapshot. You can review available restore points in Settings and inspect the operation in History.</p>`),
    ],
  },
  {
    collection: 'docs', slug: 'recording-shares-and-grants', category: 'Maintain your records',
    title: 'Record shares and equity grants',
    description: 'Record issued shares, stock options, and RSUs in Cap Table with the correct stakeholder, share class, equity plan, and vesting schedule.',
    summary: 'Connect each security to its holder, terms, and vesting schedule.',
    related: ['managing-equity-plans', 'vesting-and-option-pools', 'recording-a-departure'],
    sections: [
      section('before-you-record', 'Gather the terms first', `<p>A security record describes an issuance or award. Have the supporting company records available before entering quantities, dates, prices, and vesting terms. Recording an item in Cap Table does not itself approve or execute a legal issuance.</p><p>Create the stakeholder who owns the security. For issued shares, create the relevant share class. For options or RSUs granted under an equity plan, create that plan and verify its available reserve.</p>`),
      section('record-shares', 'Record issued shares', `<p>Use <strong>Issue security</strong> and select the appropriate security type. For shares, identify the stakeholder, share class, issued quantity, date, and price per share. Use the actual issued quantity rather than the class’s authorized share limit.</p><p>The app supports share certificates with reverse vesting, including founder restricted stock. Enter the vesting terms when they apply. Unvested issued shares remain outstanding shares in the app’s ownership calculations.</p><p>After saving, check the stakeholder’s detail page and the Cap table view. Attach the supporting agreement to the relevant record when available.</p>`),
      section('record-awards', 'Record options or RSUs', `<p>Select the award type, holder, grant quantity, and date. Choose the equity plan the award draws from, or identify it as outside every plan when that matches the actual award. An option record also carries its strike price and applicable option terms.</p><p>The app checks whether a selected plan can hold that kind of award on the grant date and whether the new award fits within its available reserve. An award outside every plan still contributes to fully diluted ownership, but draws no plan reserve. Warrants do not draw equity-plan reserves.</p><p>Options and RSUs represent different instruments. An option’s strike price and exercise process should not be used as a substitute for recording an RSU award and its settlement.</p>`),
      section('enter-vesting', 'Enter the vesting schedule', `<p>Set the vesting start, duration, cliff, and cadence from the agreement. The app supports monthly, quarterly, and annual schedules, as well as custom dated tranches. A grant date and a vesting start date can differ; keep both consistent with the source records.</p><p>Review the vesting display after saving. A vesting schedule changes how much is vested at a given date. It does not automatically remove unvested issued shares from outstanding ownership or unvested options from the fully diluted count.</p>`),
      section('record-later-events', 'Record exercises, settlements, and departures', `<p>Use the security’s available actions for subsequent events instead of changing an original grant quantity to approximate the result. The app can record an option exercise, issue its share certificate, settle an RSU award, and record cancellations or other supported events.</p><p>An option exercise and its certificate are related records. When an exercise is recorded before its certificate is issued, the app keeps those exercised units in the grant-side count until the certificate represents them.</p><p>When a holder leaves, use the departure workflow and review the effect on unvested awards and any exercise window. A plan’s recycling rules determine whether returned shares go back to the same plan, leave its reserve, or move to a successor. Check History and the plan balance after the action.</p>`),
    ],
  },
  {
    collection: 'docs', slug: 'managing-equity-plans', category: 'Maintain your records',
    title: 'Manage equity incentive plans',
    description: 'Create and maintain equity incentive plans in Cap Table, review committed and available shares, and manage reserve changes and recycling rules.',
    summary: 'Track plan reserves, award assignments, and share recycling.',
    related: ['reconciling-plan-balances', 'importing-a-cap-table', 'vesting-and-option-pools'],
    sections: [
      section('create-a-plan', 'Create a plan', `<p>Open <strong>Share classes</strong> to manage equity incentive plans. Each plan has a name, an adoption date, an initial reserve, permitted award types, and an optional expiration date. A company can have several plans.</p><p>Enter the terms of the adopted plan. Assign an underlying share class where applicable. Options and RSUs identify the plan they draw from; warrants do not draw from a plan. An award can also be recorded outside every plan when appropriate.</p>`),
      section('read-the-balance', 'Read the plan balance', `<dl><dt>Authorized</dt><dd>The plan’s reserve adjusted for applicable transfers and share flows from other plans.</dd><dt>Committed</dt><dd>The shares drawn by awards, adjusted for recorded events and the plan’s recycling rules.</dd><dt>Available</dt><dd>Authorized minus committed. These are the shares the plan can still use for new eligible awards.</dd></dl><p>For example, a plan with 1,000,000 authorized shares and 250,000 committed shares has 750,000 available shares. This simple example assumes no other transfers or recycling events.</p><p>The company’s fully diluted count can include the available shares of open plans. Available shares from a retired plan are excluded. Imported awards may leave a plan overcommitted; the app shows that condition instead of rewriting the historical award quantities.</p>`),
      section('change-the-reserve', 'Change the reserve with a dated event', `<p>Use a reserve change to record a later increase or decrease. Keep the effective date aligned with the company’s records. The app retains the dated movements so a historical cap table can use the reserve that existed at that time.</p><p>A transfer between plans moves available shares from one plan to another. It does not increase the company’s aggregate reserve. The source needs enough available shares on the transfer date and in the current records, and the destination must be open.</p><p>A new or enlarged award cannot exceed the selected plan’s available shares. A reserve reduction cannot leave the plan below its commitments.</p>`),
      section('understand-recycling', 'Understand share recycling', `<p>Recycling rules determine what happens to shares when an award is cancelled, expires, is exercised or settled, or when related shares are repurchased or transferred. A rule can return shares to the plan, retire them from availability, or direct them into another plan.</p><p>By default, cancellations and expirations return shares. Exercises and settlements keep the shares committed rather than making them available for a second grant. Repurchases and transfers also default to keeping them drawn. These are application defaults; confirm that the configured rules match the actual plan.</p><p>Rules affect the balance calculated from recorded events. Review existing awards and the balance before changing a rule. The app refuses a change that would leave the plan overcommitted.</p>`),
      section('retire-a-plan', 'Retire a plan without deleting its awards', `<p>Retiring a plan closes it to awards dated after its retirement date. Its awards and history remain. The retirement date cannot precede the latest recorded award or reserve change.</p><p>The retirement workflow can transfer available shares to a successor plan and redirect rules that would otherwise return shares to the retired plan. Review those choices against the company’s plan documents.</p><p>An unused, unreferenced plan can be deleted. A plan with awards or other references should be retired instead. The app can reopen a retired plan when needed.</p>`),
    ],
  },
  {
    collection: 'docs', slug: 'modeling-a-funding-round', category: 'Plan and review',
    title: 'Model a funding round',
    description: 'Model a priced funding round in Cap Table using pre-money valuation, new investment, convertible instruments, and an option-pool target.',
    summary: 'Compare ownership before and after financing, then review a round close.',
    related: ['option-pool-top-up-dilution', 'managing-saved-scenarios', 'pre-money-and-post-money-valuation', 'resolving-financing-refusals', 'pro-rata-rights-explained'],
    sections: [
      section('check-the-starting-records', 'Check the starting records', `<p>Open <strong>Round modeling</strong> after reconciling your existing cap table. Review share classes, issued securities, unallocated equity-plan shares, and the recorded terms of every SAFE and convertible note. The scenario uses those records as its starting point.</p><p>A saved scenario is a planning tool. It does not issue securities or change ownership until you apply a reviewed round close.</p>`),
      section('enter-the-round', 'Enter the proposed terms', `<p>Enter the pre-money valuation, new investment, and target for the unallocated option pool. The <strong>Model date</strong> is the day the round is priced on: securities dated after it are not on the table, note interest accrues to it, and a pro-rata right or MFN election applies only if it is in force that day. It is also the closing date the close workflow offers.</p><p>The pool target is the intended unallocated portion of post-round fully diluted shares. It is not the same as the total plan reserve or the number of options already granted. In this model, any required pool increase is applied pre-money.</p><p>Start with one proposed set of terms and change one assumption at a time. This makes it easier to identify why a holder’s percentage changes.</p>`),
      section('review-conversions', 'Review conversions and ownership', `<p>The app models SAFE and note conversions using the recorded cap, discount, and instrument type. Pre-money and post-money SAFEs use different capitalization bases. Preferred share classes may also produce an anti-dilution adjustment when configured and triggered.</p><p>Read the before-and-after ownership view alongside the conversion and pool results. In this model, the new investment divided by pre-money valuation plus new investment gives the new-money investor group’s modeled percentage. Conversions, pool increases, and anti-dilution adjustments affect the pre-money capitalization, share price, and distribution of the remaining ownership. Reconcile actual closing quantities after whole-share rounding.</p><p>See <a href="/guides/understanding-equity-dilution/">Understand equity dilution</a> for a simple example and the assumptions that distinguish it from a more complex round.</p>`),
      section('rights-and-elections', 'Elect pro-rata checks and MFN terms', `<p>Under <strong>Financing ID, round size and elections</strong> the model lists every pro-rata right recorded on a security and every MFN election recorded on a SAFE or note. Enter the check each holder elects, up to the entitlement the right produces on its own basis: a fixed percentage of the round, the holder’s pre-round fully diluted ownership, or a YC side-letter denominator. Tick an MFN election to apply it to this financing; the instrument’s original terms stay on record and the breakdown shows both.</p><p>Choose the round size convention the term sheet uses. <strong>Fixed total</strong> fits elected checks inside the investment entered and leaves the rest for other investors; <strong>Additional</strong> adds them on top. Either way the share price, conversions, anti-dilution and pool top-up are solved once over the whole round, so an election never changes another holder’s figures by a percentage applied after the fact.</p><p>The <strong>Participation rights and elections</strong> card shows each holder’s maximum entitlement, elected amount, resulting whole shares, and any unmet or excess amount, along with the rounding between the checks and the shares they buy. An election above its entitlement, or one that buys no whole share, is refused with the reason and the close is not offered until it is corrected. The <strong>Financing ID</strong> is what rights and elections name; give it a stable value when a right applies only to a specific financing.</p>`),
      section('save-a-scenario', 'Save and compare scenarios', `<p>Save a scenario to return to its proposed terms, model date and elections. Use descriptive names that identify the valuation, investment, or pool assumption being considered.</p><p>Scenario results depend on the underlying company records. A saved scenario remembers the cap table it was saved against: when that table has changed, the view says so, the figures shown follow the current records, and the round cannot be closed until the scenario is saved again. Saving a scenario does not make the underlying cap table a frozen historical snapshot.</p>`),
      section('close-a-round', 'Review carefully before closing', `<p>Use the close-round workflow only when you intend to apply the financing to the cap table. Choose or create the preferred class, allocate the investment between investors, and select the equity plan that receives the pool top-up.</p><p>Review the proposed certificates, conversion records, and reserve change before confirming. A round close issues the modeled securities, marks converted instruments accordingly, and updates the destination plan. A restore point is taken before the close.</p><p>The model follows the app’s calculation conventions. Reconcile the final results with the signed financing terms before recording the close. Export the resulting cap table and use History to review the transaction.</p>`),
    ],
  },
  {
    collection: 'docs', slug: 'exports-and-history', category: 'Plan and review',
    title: 'Exports, backups, and history',
    description: 'Choose the right Cap Table export, save company backups, review restore points, and inspect the permanent transaction history.',
    summary: 'Understand reports, company backups, restore points, and the audit trail.',
    related: ['importing-a-cap-table', 'reading-a-historical-cap-table', 'cap-table-maintenance-checklist'],
    sections: [
      section('choose-an-export', 'Choose the right export', `<p>Use a CSV export when you need tabular records for review or further analysis. Use a company JSON backup when you need data that can be imported back into Cap Table.</p><dl><dt>Cap table CSV</dt><dd>An export of the ownership view. Check the as-of date and ownership basis before exporting.</dd><dt>Stakeholder statement</dt><dd>A holder-specific view of securities and ownership that can be printed, saved as PDF through the print dialog, or exported to CSV.</dd><dt>Report CSV</dt><dd>The output of a selected report with its reporting period and assumptions.</dd><dt>Company JSON backup</dt><dd>A company data export intended for backup and re-import into the app.</dd></dl>`),
      section('save-a-backup', 'Save a company backup', `<p>In <strong>Settings</strong>, use the company export action to download a JSON backup. Check the selected company before exporting. Keep the downloaded file somewhere you can retrieve independently of the working cap table.</p><p>Before a significant import or restructuring, save a fresh backup and record what it represents. A descriptive filename or accompanying note can identify the company and the point in time.</p><p>Document attachments are stored as separate files in Puter. Do not treat a JSON export as a downloadable archive of every attachment; retain supporting documents separately.</p>`),
      section('use-restore-points', 'Understand restore points', `<p>The app takes restore points before operations such as a round close, stock split, import, or wipe when there is prior data to preserve. Settings lists the available points.</p><p>A restore point describes an earlier company state. Restoring it changes the working records, so review the point and the confirmation before proceeding. A first import into an empty company may not have an earlier dataset to restore.</p><p>A CSV report and a restore point serve different purposes. The report is a readable output; the restore point is used to recover an earlier working state. Follow <a href="/docs/restoring-company-data/">Restore company data</a> for replacement, new-company import, retention, and verification steps.</p>`),
      section('read-history', 'Read the permanent history', `<p><strong>History</strong> records business transactions with their actor, recording time, effective dates where applicable, and before-and-after records. Use its filters to find changes. History exports to JSON or CSV include the entire trail regardless of those filters. See <a href="/docs/transaction-history/">Filter and inspect transaction history</a> for date ranges, pagination, original values, and outcomes.</p><p>Earlier events remain when you import, undo, wipe, or restore data. If the app starts tracking an existing company without its earlier transaction trail, the initial baseline explicitly identifies that earlier history as incomplete.</p><p>The recording date tells you when an action was entered. An effective date describes when the underlying event applies. The dates can differ, especially when adding a historical issuance or correction.</p>`),
      section('handle-sync-messages', 'Respond to save and recovery messages', `<p>Keep an eye on the app’s save and connection messages. If another tab or device changes the same company and a save is refused, reload to pick up the newer records before continuing.</p><p>If the app reports an unfinished change, follow the recovery message and its retry action. A failed cloud save is not confirmed simply because an earlier screen showed the values.</p><p>The History view and backups help with review and recovery, but they do not replace the underlying company approvals and agreements.</p>`),
    ],
  },
  {
    collection: 'docs', slug: 'reading-a-historical-cap-table', category: 'Plan and review',
    title: 'Read and export a historical cap table',
    description: 'Choose an as-of date, ownership basis, and option-pool setting in Cap Table, then export an ownership report that explains its assumptions.',
    summary: 'Review ownership on a selected date and reconcile the share counts.',
    related: ['authorized-outstanding-and-fully-diluted-shares', 'printing-cap-tables-and-statements', 'dates-numbers-and-rounding'],
    sections: [
      section('choose-the-date', 'Choose the company and reporting date', `<p>Open <strong>Cap table</strong> and check the selected company. Use <strong>As of</strong> to choose the date the report should represent. The view recalculates ownership from the dated records available in the company. Use <strong>Back to today</strong> to return to the current view.</p><p>Beside the date field, a row of shortcut chips jumps to <strong>Today</strong> and to the most recent dates on which securities were issued, up to eight of them. They are a fast way to compare the table immediately before and after a financing without typing dates.</p><p>A historical view is useful when comparing ownership before and after an issuance, transfer, or financing. Start with the day before the event and then select its effective date. This helps isolate the change without editing the working records.</p>`),
      section('choose-the-basis', 'Choose the ownership basis', `<p>Select outstanding or fully diluted ownership. Outstanding counts issued share certificates. Fully diluted also includes the app’s counted options, RSUs, and warrants. The <strong>Include pool</strong> control applies to the fully diluted view and includes available shares from open equity plans.</p><p>SAFEs and notes appear separately as convertible instruments. They do not enter the ownership share denominator until conversion. An unvested option can count toward fully diluted ownership even though it is not yet exercisable.</p><p>Read <a href="/guides/authorized-outstanding-and-fully-diluted-shares/">Authorized, outstanding, and fully diluted shares</a> for a numerical comparison of these measures.</p>`),
      section('reconcile-differences', 'Explain differences between reports', `<ol><li>Compare the company and as-of date.</li><li>Match the ownership basis and pool setting.</li><li>Check issuance, exercise, settlement, cancellation, and transfer dates.</li><li>Check whether a funding round converted any SAFEs or notes.</li><li>Check for a stock split between the two dates.</li></ol><p>Reports before a recorded stock split read in pre-split units. A larger share count after a split does not necessarily mean that a holder’s ownership percentage increased.</p>`),
      section('export-the-view', 'Export the selected view', `<p>Choose <strong>Export CSV</strong> for a spreadsheet-readable report or <strong>Print report</strong> for a printable version. Your browser’s print dialog can save the report as a PDF. Inspect the report’s date, basis, and pool treatment before sharing it.</p><p>The report reflects the records currently available for the chosen effective date. It is not a frozen copy of what someone saw on that date: later corrections to historical records can change the result. Use <a href="/docs/exports-and-history/">History and company backups</a> when you also need to understand when a change was entered or retain a particular version.</p>`),
    ],
  },
  {
    collection: 'docs', slug: 'managing-stakeholders', category: 'Maintain your records',
    title: 'Manage stakeholders and equity statements',
    description: 'Add and update stakeholders in Cap Table, inspect their securities, and export a holder-specific equity statement as CSV or PDF.',
    summary: 'Maintain holder profiles and prepare individual equity statements.',
    related: ['recording-shares-and-grants', 'transferring-and-repurchasing-shares', 'recording-a-departure'],
    sections: [
      section('add-a-holder', 'Create a stakeholder record', `<p>Open <strong>Stakeholders</strong> and add the person or entity that holds the security. Enter a name, choose the stakeholder type, and add an email address if useful. Use the holder’s identity from the supporting records and check whether that holder already exists before creating another profile.</p><p>A stakeholder is the holder record. It does not create an ownership interest by itself. Record each issuance or award separately and assign it to that stakeholder. The same holder can have several certificates, grants, or convertible instruments.</p><p>The standalone stakeholder form warns about a duplicate name but permits distinct holders with that name. Their records stay separate, while the recent activity feed matches text by name and can be ambiguous. Use the record-filtered History trail for identification. Renaming a holder preserves earlier names for activity matching; it does not transfer ownership.</p><p>An email address is optional contact information. Adding it does not send an invitation or grant access to the company.</p>`),
      section('review-the-profile', 'Review holdings in one place', `<p>Open the holder’s detail page to inspect securities and ownership. Check the individual quantities, instrument types, dates, and vesting terms rather than relying only on the percentage at the top.</p><p>Use <strong>Edit</strong> to correct profile details and <strong>History</strong> to inspect recorded changes associated with the stakeholder. Updating a name is different from moving ownership to another person or entity. Use the <a href="/docs/transferring-and-repurchasing-shares/">share transfer workflow</a> for an actual change of holder.</p>`),
      section('prepare-a-statement', 'Prepare an equity statement', `<ol><li>Check that you have opened the intended company and holder.</li><li>Reconcile the listed securities with the holder’s agreements and recorded transactions.</li><li>Choose <strong>Export CSV</strong> for tabular data, or <strong>Print or save as PDF</strong> for a readable statement.</li><li>Review the resulting file’s holder, report date, currency, quantities, and ownership basis before sharing it.</li></ol><p>The stakeholder statement describes current holdings. For an ownership report on an earlier date, use the <a href="/docs/reading-a-historical-cap-table/">as-of cap table</a>. A downloaded statement does not give its recipient live access to the company’s working records.</p>`),
      section('keep-the-history', 'Keep departures and ownership changes explicit', `<p>A person leaving the company may still hold shares or vested awards. Use <strong>Mark departed</strong> to review the departure workflow and retain the holder’s records. Do not treat departure as a reason to remove all of the person’s securities.</p><p>Record exercises, settlements, cancellations, transfers, and repurchases through their relevant actions. These events explain changes that would otherwise look like unexplained edits to an original quantity. See <a href="/docs/recording-a-departure/">Record a stakeholder departure</a> for the actions handled together and those that require a separate step.</p>`),
    ],
  },
  {
    collection: 'docs', slug: 'transferring-and-repurchasing-shares', category: 'Ownership changes',
    title: 'Transfer or repurchase shares',
    description: 'Record a share transfer or company repurchase in Cap Table while preserving the original certificate, successor records, and effective date.',
    summary: 'Move shares between holders or record a company buyback.',
    related: ['transfers-repurchases-and-new-issuances', 'correcting-and-deleting-records', 'reading-a-historical-cap-table'],
    sections: [
      section('choose-the-certificate', 'Start with the existing certificate', `<p>Open <strong>Securities</strong>, find the share certificate, and choose its <strong>Transfer or repurchase</strong> action. Check the holder, class, certificate label, and available quantity against the transaction records. This workflow applies to issued shares.</p><p>The app closes the original certificate on the transfer date and creates successor certificates for the holdings that continue. Keeping that chain allows earlier cap tables to show the original certificate and later cap tables to show the result.</p>`),
      section('enter-the-transfer', 'Enter the recipient and terms', `<ol><li>Choose the receiving party: an existing stakeholder, a new stakeholder, or <strong>The company (repurchase)</strong>.</li><li>Enter the number of shares. Use a whole number no larger than the certificate’s quantity.</li><li>Enter the transfer date. It cannot precede the certificate’s issuance date.</li><li>Enter the transaction’s price per share. A blank price records zero consideration, so leave it blank only when that matches the transaction.</li><li>Read the summary and select <strong>Record transfer</strong> when the proposed records match the event.</li></ol>`),
      section('understand-the-result', 'Understand transfers and repurchases', `<p>For a transfer to another holder, the recipient receives a new certificate. If only part of the original holding moves, a separate certificate holds the seller’s remainder. A transfer of 20,000 shares from a 100,000-share certificate therefore leaves 80,000 with the seller and 20,000 with the recipient, with no change in aggregate outstanding shares.</p><p>For a company repurchase, the repurchased shares are retired in this app. No buyer certificate is created for those shares, and outstanding shares decrease. A partial repurchase still creates a successor certificate for the seller’s remaining holding.</p><p>The recipient’s transaction price is recorded separately from the original issue price used for preference calculations. Check both when reconciling a secondary sale.</p>`),
      section('review-vesting-and-history', 'Review vesting and the certificate chain', `<p>If transferred stock is subject to vesting, read the warning before saving. In this workflow, the buyer’s certificate carries no vesting schedule, while the seller’s remainder retains a proportionally adjusted schedule. A transfer can therefore reduce the shares reported as unvested. Confirm that this treatment matches the event you are recording.</p><p>After saving, review both holders, the successor certificates, and History. Compare cap tables before and on the transfer date. For repurchases associated with a plan, also review the plan balance and its recycling rules.</p>`),
    ],
  },
  {
    collection: 'docs', slug: 'recording-a-departure', category: 'Ownership changes',
    title: 'Record a stakeholder departure',
    description: 'Review option cancellations, exercise deadlines, RSU follow-up, and restricted-stock repurchases when a stakeholder leaves the company.',
    summary: 'Review a departure’s effect on awards and outstanding shares.',
    related: ['transferring-and-repurchasing-shares', 'managing-equity-plans', 'vesting-and-option-pools', 'post-termination-exercise-windows'],
    sections: [
      section('set-the-departure-date', 'Open the departure review', `<p>Open the stakeholder’s detail page and choose <strong>Mark departed</strong>. Enter the termination date from the company’s records. The workflow uses that date to calculate the proposed effect on the holder’s option grants.</p><p>Check the grant dates, previous exercises, and vesting schedules before continuing. A date that precedes a grant or conflicts with an already recorded exercise can prevent the workflow from proceeding. Correct the underlying records when they are wrong; do not change a real termination date simply to bypass a message.</p>`),
      section('review-option-grants', 'Review each option grant', `<p>The review identifies unvested options to cancel and the remaining vested options. Previously exercised units are accounted for when calculating what remains. The destination of cancelled units follows the grant’s plan recycling rules.</p><p>The app initially proposes an exercise deadline 90 days after departure, shortened when the grant expires sooner. This is an application default, not a statement of the holder’s contractual or tax rights. Set the deadline from the actual award terms. Clearing the field leaves the grant’s remaining term in force; it does not remove the grant’s expiration.</p><p>A grant whose exercise window already closed before the departure is handled separately. Review its item in <strong>Needs attention</strong> to record the expiration-related cancellation instead of expecting the departure to cancel it again.</p>`),
      section('handle-separate-actions', 'Handle RSUs and restricted stock separately', `<p>The departure review also identifies RSU and reverse-vesting stock follow-up. Recording the departure does not perform every action mentioned in those notes.</p><ul><li><strong>RSUs:</strong> review the unvested, unsettled units and record any required cancellation from the award.</li><li><strong>Reverse-vesting stock:</strong> record an actual company buyback through the <a href="/docs/transferring-and-repurchasing-shares/">share repurchase workflow</a>. The departure itself does not retire the certificate.</li><li><strong>Vested holdings:</strong> keep shares and surviving awards recorded unless another transaction changes them.</li></ul>`),
      section('confirm-and-reconcile', 'Confirm and reconcile the changes', `<p>Review the proposed cancellations and deadlines before confirming the departure. Then inspect the holder’s profile, affected grants, plan balances, and History. Complete the separate award cancellations or repurchases that the underlying records require.</p><p>For example, an unexercised 48,000-unit option grant that has vested 24,000 units at departure may leave 24,000 vested options and cancel 24,000 unvested units. That example assumes no acceleration, previous cancellation, or expired exercise window. The actual review uses the grant’s recorded terms and events.</p>`),
    ],
  },
  {
    collection: 'docs', slug: 'recording-a-stock-split', category: 'Ownership changes',
    title: 'Record a stock split',
    description: 'Preview and record a forward or reverse stock split in Cap Table, including share quantities, per-share prices, plan reserves, and rounding.',
    summary: 'Restate quantities and per-share terms with a dated split.',
    related: ['stock-splits-and-ownership', 'dates-numbers-and-rounding', 'restoring-company-data'],
    sections: [
      section('prepare-the-records', 'Check the units before recording', `<p>Open <strong>Share classes</strong>, find <strong>Stock splits</strong>, and select <strong>Record split</strong>. Have the approved ratio and effective date available. Save a company backup before recording a significant restatement.</p><p>The split restates stored quantities and per-share amounts across the company. If you are entering a split after the fact, check whether any securities or valuations have already been entered in post-split units. The app restates those records too, so mixing units can apply the same adjustment twice. Review the warning for records dated after the split.</p>`),
      section('enter-the-ratio', 'Enter the ratio and effective date', `<p>Enter how many new shares replace the old shares. Use whole numbers on both sides: <strong>2 for every 1</strong> doubles quantities, while <strong>1 for every 10</strong> reduces them to one tenth. A factor of 1.5 is entered as <strong>3 for every 2</strong>.</p><p>The effective date must be today or earlier because the app restates the working records as soon as the split is recorded. This workflow does not schedule a future split.</p>`),
      section('check-the-preview', 'Review quantities, prices, and rounding', `<p>The preview compares outstanding shares, fully diluted shares, plan reserves, and the recorded valuation per share where available. Quantities scale with the ratio, while per-share prices scale inversely. A 2-for-1 split would turn 10,000 options at a $2 strike into 20,000 options at a $1 strike, assuming no rounding.</p><p>The app also adjusts relevant class terms and recorded valuations. SAFE and note principal amounts are monetary balances, so they do not multiply with the share count.</p><p>Whole-share rounding can add or remove units, particularly in a reverse split. Review the reported difference. The app does not model cash paid in place of fractional shares, so reconcile any such payment separately.</p>`),
      section('record-and-verify', 'Record and verify both sides of the date', `<p>Select <strong>Record split</strong> after reviewing the preview. A restore point is taken before the operation. Check the resulting securities, prices, plan reserves, and split history.</p><p>Use the as-of cap table to inspect a date before the split and the effective date itself. Earlier dates read in pre-split units. Without rounding or another transaction, a proportional split changes unit counts while leaving ownership percentages unchanged. See the SEC’s <a href="https://www.investor.gov/introduction-investing/investing-basics/glossary/stock-split">stock split explanation</a> for the basic concept.</p>`),
    ],
  },
  {
    collection: 'docs', slug: 'modeling-an-exit', category: 'Plan and review',
    title: 'Model an exit waterfall',
    description: 'Use Cap Table exit scenarios to compare sale proceeds by holder, preferred-stock preferences, convertible instruments, and award treatment.',
    summary: 'Compare modeled sale proceeds and save the deal assumptions.',
    related: ['liquidation-preferences-explained', 'exit-proceeds-and-exercise-cost', 'managing-saved-scenarios', 'exit-waterfall-step-by-step', 'exit-breakeven-points'],
    sections: [
      section('review-the-inputs', 'Check the records that drive the waterfall', `<p>Open <strong>Exit scenarios</strong>. Before modeling proceeds, review issued shares, preferred-class terms, convertible balances, option strike prices, RSUs, and any recorded acceleration terms. A correct ownership percentage alone is not enough to calculate a sale distribution.</p><p>The model uses the current company records as of the <strong>Model date</strong>: note interest and preferred dividends accrue to it, and a security dated after it is not on the table. Unallocated plan capacity does not receive a holder payout. The <a href="/guides/liquidation-preferences-explained/">liquidation preference guide</a> explains why holders with similar ownership percentages can receive different proceeds.</p>`),
      section('enter-the-deal-assumptions', 'Enter the sale and award assumptions', `<ol><li>Give the scenario a descriptive name.</li><li>Enter the <strong>Exit value</strong>. The app treats this as the total sale price before escrow, fees, and tax; those deductions are not modeled.</li><li>Choose whether unvested awards at close <strong>Participate</strong> or are <strong>Cancelled</strong>.</li><li>Review <strong>Assume a change of control</strong> against the recorded acceleration terms.</li></ol><p>The change-of-control assumption applies the app’s recorded acceleration logic. A double trigger assumes the holder is also terminated at close. When all unvested awards already participate, acceleration does not change that participation result. These controls model assumptions; they do not determine the actual deal terms.</p>`),
      section('read-the-results', 'Read the results in payment order', `<p>Start with the <strong>Waterfall summary</strong>, then review preferred classes, convertibles, award treatment, and proceeds by holder. Inspect the amount actually paid, not just a preference claim or an as-converted comparison.</p><p>In this model, convertible notes are treated as debt repayments at exit. SAFEs are evaluated under the modeled cash-out and conversion outcomes. Preferred-class rights affect preference payments and participation in the remainder. If sale proceeds are insufficient, a claim can exceed its payment.</p><p><strong>Breakeven points</strong> identify modeled sale values where outcomes change. Select one to inspect the waterfall at that value, then compare results above and below it.</p>`),
      section('caps-and-dividends', 'Read participation caps and dividend claims', `<p>When a preferred class carries dated participation-cap or dividend terms (see <a href="/docs/configuring-share-classes/">Configure share classes</a>), the waterfall settles every class’s election together: each class takes its preference and accrued dividends off the top and then participates up to each holder’s cap, or converts to common when that pays more, with the other classes’ choices taken into account. The classes table marks a class whose cap is reached and shows its dividend claim beside its preference.</p><p>A <strong>dividend calculation</strong> card per class shows what each certificate accrues on, each dated segment at its rate and convention, and what was declared and paid, so the claim can be reconciled to the charter. Proceeds are conserved: a residual that no holder is eligible to receive, because every participant is capped, is reported as unallocated rather than assigned. A table carrying these terms alongside an unconverted SAFE is refused with the reason; model and close the conversion first. The breakeven card does not run for a table with these terms.</p>`),
      section('save-and-compare', 'Save distinct scenarios', `<p>Select <strong>Save scenario</strong> to retain the sale value and award assumptions. Saving with an existing name updates that scenario. Use a different name to keep another case for comparison.</p><p>A saved scenario retains inputs and the model date, not a frozen copy of the company. It remembers the cap table it was saved against and says so when that table has changed; the results shown follow the current records. Saving a scenario does not record an acquisition, distribute money, or close securities. Reconcile modeled proceeds with the final transaction calculations before using them for a real distribution.</p>`),
    ],
  },
  {
    collection: 'guides', slug: 'what-is-a-cap-table', category: 'Ownership basics',
    title: 'What is a cap table?',
    description: 'Learn what a capitalization table records, how ownership percentages are calculated, and why outstanding and fully diluted shares differ.',
    summary: 'Read a capitalization table and understand the ownership denominator.',
    related: ['authorized-outstanding-and-fully-diluted-shares', 'getting-started', 'cap-table-glossary', 'common-and-preferred-stock'],
    sections: [
      section('the-basic-definition', 'A record of company ownership', `<p>A cap table, short for capitalization table, records a company’s equity holders and the securities associated with them. It helps answer who holds what, how much has been issued, and how ownership changes after a grant, financing, or other transaction.</p><p>A useful cap table connects holders to share classes, quantities, issuance dates, and instrument terms. The percentages are calculated from those records. They are not a substitute for them.</p><p>Shares represent ownership in a company, and different classes can carry different rights. The SEC’s <a href="https://www.investor.gov/introduction-investing/investing-basics/investment-products/stocks">introduction to stocks</a> explains the basic distinction between common and preferred stock.</p>`),
      section('calculate-ownership', 'Calculate an ownership percentage', `<p>For a simple company with one share class, divide a holder’s shares by the total shares counted in the chosen ownership basis.</p><div class="site-formula">Ownership % = holder shares ÷ total counted shares × 100</div><p>Suppose two founders hold 6,000,000 and 4,000,000 shares, with no other instruments or reserve. Their ownership percentages are 60% and 40%.</p><div class="site-table" tabindex="0" role="region" aria-label="Simple ownership example"><table><caption>Illustrative company with 10 million issued shares</caption><thead><tr><th scope="col">Holder</th><th scope="col">Shares</th><th scope="col">Ownership</th></tr></thead><tbody><tr><th scope="row">Founder A</th><td>6,000,000</td><td>60%</td></tr><tr><th scope="row">Founder B</th><td>4,000,000</td><td>40%</td></tr><tr><th scope="row">Total</th><td>10,000,000</td><td>100%</td></tr></tbody></table></div><p>A percentage is meaningful only when its denominator and date are clear. “One percent of the company” can describe different share counts under different assumptions.</p>`),
      section('outstanding-and-fully-diluted', 'Outstanding and fully diluted shares', `<p>Outstanding ownership focuses on issued shares. Fully diluted ownership generally also considers instruments that can become shares and often includes the unallocated option pool. The precise definition should be checked against the relevant agreement or report. Cooley explains this distinction in <a href="https://www.cooleygo.com/option-grants-fully-diluted-issued-outstanding/">Option Grants: Fully Diluted or Issued and Outstanding</a>.</p><p>In Cap Table, outstanding counts issued share certificates. Fully diluted adds option grants, unsettled RSUs, and warrants, with an option to include available shares from open equity plans. SAFEs and convertible notes are excluded from these ownership counts until conversion.</p><p>If the example company adds a 2,000,000-share unallocated reserve and includes it in the fully diluted basis, the denominator becomes 12,000,000. Founder A then has 50% on that basis, even though the founder still holds 6,000,000 shares.</p>`),
      section('what-percentages-do-not-show', 'What an ownership percentage does not show', `<p>A cap table percentage does not by itself determine voting power, the value of an award, or the proceeds a holder would receive in a sale. Share-class rights, preferences, exercise prices, and other terms can affect those outcomes.</p><p>Vesting is another separate question. In Cap Table, issued shares can be outstanding while still subject to vesting, and unvested option grants still contribute to the fully diluted count. Do not use an ownership percentage as a shortcut for the number of vested or immediately exercisable units.</p>`),
      section('maintain-the-record', 'Keep the table connected to its records', `<p>Update the cap table when securities are issued, exercised, settled, cancelled, transferred, or converted. Retain the supporting agreements and the dates that explain each change.</p><p>Before sharing an export, check the company, date, ownership basis, and treatment of the unallocated pool. These details let another reader reproduce the percentages instead of guessing at the assumptions.</p><p>To put this into practice, follow <a href="/docs/getting-started/">Get started with Cap Table</a> or <a href="/docs/importing-a-cap-table/">import your existing records from CSV</a>.</p>`),
    ],
  },
  {
    collection: 'guides', slug: 'understanding-equity-dilution', category: 'Fundraising',
    title: 'Understand equity dilution',
    description: 'See how issuing new shares changes ownership percentages, with a worked funding-round example and an explanation of option pools and convertibles.',
    summary: 'Work through a funding round and see why percentages change.',
    related: ['modeling-a-funding-round', 'pre-money-and-post-money-valuation', 'vesting-and-option-pools'],
    sections: [
      section('what-dilution-means', 'What dilution means', `<p>Ownership dilution occurs when the number of shares counted in a company increases while a holder’s share count stays the same. The holder owns a smaller percentage of the larger total.</p><p>Dilution describes a percentage change. It does not, by itself, establish whether the monetary value of the holding has increased or decreased. A financing can change both the company’s capitalization and its implied value.</p>`),
      section('a-simple-funding-round', 'A simple funding-round example', `<p>Assume a company has 10,000,000 shares before a round. A founder owns 6,000,000 shares, or 60%. Investors propose a $2,000,000 investment at an $8,000,000 pre-money valuation.</p><p>This example has one share class and excludes convertibles, option-pool changes, anti-dilution adjustments, fees, and secondary sales.</p><ol><li>Price per share: $8,000,000 ÷ 10,000,000 = <strong>$0.80</strong>.</li><li>New investor shares: $2,000,000 ÷ $0.80 = <strong>2,500,000</strong>.</li><li>Post-round total: 10,000,000 + 2,500,000 = <strong>12,500,000 shares</strong>.</li><li>Founder ownership: 6,000,000 ÷ 12,500,000 = <strong>48%</strong>.</li></ol><div class="site-table" tabindex="0" role="region" aria-label="Before and after funding example"><table><caption>Illustrative ownership before and after the round</caption><thead><tr><th scope="col">Holder</th><th scope="col">Before</th><th scope="col">After</th></tr></thead><tbody><tr><th scope="row">Founder</th><td>60%</td><td>48%</td></tr><tr><th scope="row">Other existing holders</th><td>40%</td><td>32%</td></tr><tr><th scope="row">New investors</th><td>0%</td><td>20%</td></tr></tbody></table></div>`),
      section('percentage-points', 'Percentage points and relative dilution', `<p>The founder’s ownership falls from 60% to 48%. That is a decrease of <strong>12 percentage points</strong>. Relative to the original 60% stake, the decrease is <strong>20%</strong>: (60 − 48) ÷ 60.</p><p>The founder still holds 6,000,000 shares. The denominator changed. Distinguishing the share count, percentage-point change, and relative change prevents different uses of “dilution” from being confused.</p>`),
      section('pool-increases-and-convertibles', 'Why actual rounds can differ', `<p>A pre-money option-pool increase expands the capitalization used to price the financing. It can therefore dilute existing holders in addition to the shares issued for new investment. Cooley’s <a href="https://www.cooleygo.com/negotiating-option-pool/">option-pool explanation</a> works through why the size and timing of the pool matter.</p><p>SAFEs and convertible notes can also add shares at conversion. The outcome depends on the instrument’s terms, including any valuation cap, discount, and capitalization definition. Pre-money and post-money SAFE calculations are not interchangeable. Y Combinator publishes its <a href="https://www.ycombinator.com/safe">SAFE documents and explanatory materials</a>.</p><p>These additional terms are why the simple example should not be applied unchanged to every financing. Review each instrument and the actual financing documents.</p>`),
      section('model-your-own-round', 'Compare scenarios in Cap Table', `<p>Use <strong>Round modeling</strong> to enter the pre-money valuation, investment amount, and unallocated-pool target. The model uses recorded securities and instrument terms to calculate the proposed capitalization.</p><p>Compare the before-and-after view by holder. Change one assumption at a time and record which terms each saved scenario represents. Saving a scenario does not close the financing or alter the cap table.</p><p>Follow <a href="/docs/modeling-a-funding-round/">Model a funding round</a> for the workflow and the review required before applying a close.</p>`),
    ],
  },
  {
    collection: 'guides', slug: 'vesting-and-option-pools', category: 'Employee equity',
    title: 'Vesting and option pools explained',
    description: 'Understand the difference between an equity grant, vesting, exercise, and an option-pool reserve with a simple four-year vesting example.',
    summary: 'Separate the grant, the vesting schedule, and the available reserve.',
    related: ['recording-shares-and-grants', 'managing-equity-plans', 'what-is-a-cap-table'],
    sections: [
      section('four-different-questions', 'Four different questions about equity', `<p>Employee equity discussions often mix together a grant’s size, vesting schedule, exercise terms, and the company’s option pool. Keeping them separate makes the cap table easier to read.</p><dl><dt>Grant</dt><dd>The award recorded for a particular holder, with its quantity and terms.</dd><dt>Vesting</dt><dd>The schedule or conditions under which rights under the award are earned.</dd><dt>Exercise</dt><dd>For an option, the action of purchasing shares under the option’s terms.</dd><dt>Available pool</dt><dd>The plan reserve that remains available for eligible future awards.</dd></dl><p>An option is not the same instrument as an issued share. Cooley’s <a href="https://www.cooleygo.com/establishing-ownership-culture-stock-vs-options/">comparison of stock and options</a> explains the distinction and how vesting can apply to each.</p>`),
      section('a-vesting-example', 'A four-year vesting example', `<p>Assume an option grant covers 48,000 shares, vests over 48 months, and has a 12-month cliff. In this illustrative schedule, 12,000 units vest at the first anniversary and 1,000 units vest each month after that. Assume continuous service and no acceleration, cancellation, or other changes.</p><div class="site-table" tabindex="0" role="region" aria-label="Illustrative vesting schedule"><table><caption>48,000-unit grant with a one-year cliff</caption><thead><tr><th scope="col">Completed service</th><th scope="col">Vested units</th><th scope="col">Vested portion</th></tr></thead><tbody><tr><th scope="row">Before 12 months</th><td>0</td><td>0%</td></tr><tr><th scope="row">12 months</th><td>12,000</td><td>25%</td></tr><tr><th scope="row">24 months</th><td>24,000</td><td>50%</td></tr><tr><th scope="row">48 months</th><td>48,000</td><td>100%</td></tr></tbody></table></div><p>This is an example, not a required schedule. Use the dates, cadence, conditions, and rounding rules in the actual award agreement.</p>`),
      section('vesting-is-not-exercise', 'Vesting is not exercise', `<p>A vested option has not necessarily been exercised, and vesting does not automatically create an issued share certificate. Some awards permit early exercise; others do not. Exercise windows and expiration dates also matter.</p><p>In Cap Table, record the vesting schedule on the award and use the exercise workflow for a later exercise. Review any resulting certificate so the issued shares and grant record remain connected.</p><p>For RSUs, use the settlement workflow rather than an option exercise. The award type determines which terms and actions are relevant.</p>`),
      section('how-the-pool-is-used', 'How an award uses a plan reserve', `<p>Suppose an equity plan has a 1,000,000-share reserve with no previous awards. A 48,000-unit grant leaves 952,000 available shares, assuming the award is eligible and no other events affect the plan.</p><p>The full grant draws from the plan when granted. The reserve does not wait for each monthly vesting installment. In the app, unvested options still count toward fully diluted ownership.</p><p>If an award is later cancelled or expires, the plan’s recycling rules determine where the affected shares go. Returning them to the same plan, retiring them from availability, and directing them to a successor are different outcomes. Confirm the rules against the plan documents.</p>`),
      section('avoid-double-counting', 'Avoid double-counting the pool', `<p>When using a fully diluted basis that includes the pool, distinguish granted awards from the <em>unallocated</em> reserve. Adding both the full original reserve and all the awards drawn from it can count the same capacity twice.</p><p>In the simple example, 48,000 granted units plus 952,000 unallocated shares account for the 1,000,000-share plan reserve. Later exercises, cancellations, transfers, and plan rules can change that reconciliation.</p><p>Read <a href="/docs/managing-equity-plans/">Manage equity incentive plans</a> to inspect balances and reserve movements, or <a href="/docs/recording-shares-and-grants/">Record shares and equity grants</a> to enter an award.</p>`),
    ],
  },
  {
    collection: 'guides', slug: 'authorized-outstanding-and-fully-diluted-shares', category: 'Ownership basics',
    title: 'Authorized, outstanding, and fully diluted shares',
    description: 'Compare authorized shares, outstanding stock, granted awards, and unallocated reserves with a worked cap table example.',
    summary: 'Understand which share counts belong in each ownership calculation.',
    related: ['what-is-a-cap-table', 'reading-a-historical-cap-table', 'managing-equity-plans'],
    sections: [
      section('separate-the-counts', 'Separate authorization from ownership', `<p>Authorized shares describe the number a company is permitted to issue under its governing documents. Outstanding shares describe issued stock still held by shareholders. Unissued authorization is not itself a holding, and it does not automatically belong in an ownership denominator.</p><p>Options and similar awards introduce another count: shares that may be issued under existing rights. A fully diluted cap table includes specified potential shares as well as outstanding stock. Cooley’s <a href="https://www.cooleygo.com/option-grants-fully-diluted-issued-outstanding/">explanation of share-count terminology</a> distinguishes authorization, actual issuance, and the fully diluted basis.</p>`),
      section('work-through-an-example', 'Work through one company’s share counts', `<p>Assume one common class is authorized for 15,000,000 shares. The company has 8,000,000 outstanding shares and a 2,000,000-share equity plan. It has granted 500,000 options from that plan, with no exercises, cancellations, or other securities.</p><div class="site-table" tabindex="0" role="region" aria-label="Share count comparison"><table><caption>Illustrative capitalization with one share class</caption><thead><tr><th scope="col">Measure</th><th scope="col">Shares</th><th scope="col">Calculation</th></tr></thead><tbody><tr><th scope="row">Authorized class shares</th><td>15,000,000</td><td>Class authorization</td></tr><tr><th scope="row">Outstanding stock</th><td>8,000,000</td><td>Issued shares still outstanding</td></tr><tr><th scope="row">Unallocated plan reserve</th><td>1,500,000</td><td>2,000,000 − 500,000</td></tr><tr><th scope="row">Fully diluted, excluding reserve</th><td>8,500,000</td><td>8,000,000 + 500,000</td></tr><tr><th scope="row">Fully diluted, including reserve</th><td>10,000,000</td><td>8,000,000 + 500,000 + 1,500,000</td></tr></tbody></table></div><p>A founder holding 4,000,000 shares owns 50% of outstanding stock and 40% on the fully diluted basis that includes the reserve. Neither figure uses the 15,000,000 authorized shares as its denominator.</p>`),
      section('avoid-reserve-confusion', 'Distinguish the class limit from the plan reserve', `<p>The equity plan’s reserve and the share class’s authorization answer different questions. In the example, subtracting outstanding shares from authorization leaves 7,000,000 unissued shares, but that is not the same as 7,000,000 shares freely available for new promises. The company already has awards and a plan reserve to account for.</p><p>When constructing the fully diluted count, add granted awards and the remaining unallocated reserve. Adding the whole 2,000,000-share reserve and the 500,000 grants on top would count those grants twice.</p>`),
      section('use-a-defined-basis', 'State the basis with the percentage', `<p>Label a percentage with its date and denominator. A report might say “40% fully diluted, including the unallocated plan reserve, as of September 1, 2026.” That is more reproducible than an unlabeled ownership percentage.</p><p>Cap Table provides outstanding and fully diluted views with a pool control. SAFEs and notes remain separate until conversion. Financing agreements can define capitalization differently, so compare the actual definition with the report before using its denominator to price a round. Follow <a href="/docs/reading-a-historical-cap-table/">Read and export a historical cap table</a> to select those controls.</p>`),
    ],
  },
  {
    collection: 'guides', slug: 'pre-money-and-post-money-valuation', category: 'Fundraising',
    title: 'Pre-money and post-money valuation explained',
    description: 'Calculate pre-money valuation, post-money valuation, share price, and investor ownership in a simple priced financing round.',
    summary: 'Connect a financing’s headline valuation to its share price.',
    related: ['understanding-equity-dilution', 'modeling-a-funding-round', 'safes-and-convertible-notes'],
    sections: [
      section('define-the-valuation', 'Identify which valuation is being quoted', `<p>Pre-money valuation describes the company’s agreed equity value before the new financing. In a simple primary financing, post-money valuation adds the new investment to that amount. Cooley’s <a href="https://www.cooleygo.com/glossary/pre-money-valuation/">definition of pre-money valuation</a> describes this relationship.</p><div class="site-formula">Post-money valuation = pre-money valuation + new investment</div><p>The formula needs a defined transaction. The examples below exclude debt conversion, changes to the option pool, fees, and secondary purchases from existing holders.</p>`),
      section('compare-the-same-headline', 'The same headline number can describe different deals', `<p>Suppose an investor contributes $3,000,000. A $12,000,000 pre-money valuation and a $12,000,000 post-money valuation produce different ownership results.</p><div class="site-table" tabindex="0" role="region" aria-label="Pre-money and post-money comparison"><table><caption>Two illustrative financings with a $3 million investment</caption><thead><tr><th scope="col">Quoted terms</th><th scope="col">Pre-money</th><th scope="col">Post-money</th><th scope="col">Investor ownership</th></tr></thead><tbody><tr><th scope="row">$12 million pre-money</th><td>$12,000,000</td><td>$15,000,000</td><td>20%</td></tr><tr><th scope="row">$12 million post-money</th><td>$9,000,000</td><td>$12,000,000</td><td>25%</td></tr></tbody></table></div><p>For these simplified terms, investor ownership equals new investment divided by post-money valuation. Always label a quoted valuation before comparing offers.</p>`),
      section('derive-the-share-price', 'Translate valuation into a price per share', `<p>Assume the first company has 6,000,000 shares in the agreed pre-round capitalization. The price is $12,000,000 ÷ 6,000,000 = <strong>$2 per share</strong>. A $3,000,000 investment buys 1,500,000 new shares. The resulting 7,500,000-share total gives the investor 20%.</p><p>A share price requires both a valuation and a share-count definition. The same headline valuation can produce a different price if the financing denominator includes a larger pool or additional converting instruments. An authorized share limit is not a substitute for that agreed capitalization.</p>`),
      section('keep-other-values-separate', 'Keep other valuation figures separate', `<p>A financing valuation, an option’s strike price, a recorded common-stock fair market value, and a future sale price describe different things. Do not copy one into a field intended for another simply because they all involve equity.</p><p>A secondary purchase moves existing shares from a seller to a buyer. It does not issue the same new shares or put the purchase price into the company, so the primary-financing example does not describe that transaction.</p><p>Use <a href="/docs/modeling-a-funding-round/">Round modeling</a> to compare the proposed financing using the company’s recorded instruments and pool assumptions. Use <a href="/docs/modeling-an-exit/">Exit scenarios</a> to explore sale proceeds.</p>`),
    ],
  },
  {
    collection: 'guides', slug: 'safes-and-convertible-notes', category: 'Fundraising',
    title: 'SAFEs and convertible notes on a cap table',
    description: 'Understand how SAFEs and convertible notes are recorded before conversion, and how caps, discounts, and interest affect financing models.',
    summary: 'Track convertible instruments without treating them as issued shares.',
    related: ['modeling-a-funding-round', 'pre-money-and-post-money-valuation', 'modeling-an-exit', 'mfn-clauses-explained', 'pro-rata-rights-explained'],
    sections: [
      section('record-the-instrument', 'Record the agreement before there is a share count', `<p>A SAFE is a simple agreement for future equity. It is not an issued share certificate. Convertible notes are debt instruments with conversion terms and can carry interest and maturity dates. Y Combinator’s <a href="https://www.ycombinator.com/blog/announcing-the-safe-a-replacement-for-convertible-notes">original SAFE explanation</a> describes the distinction between its SAFE and convertible debt.</p><p>Before conversion, retain the holder, investment amount, agreement date, and conversion terms as an instrument record. In Cap Table, select <strong>SAFE</strong> or <strong>Note</strong> when issuing a security. These instruments are listed separately from the outstanding and fully diluted ownership share counts until they convert.</p>`),
      section('understand-caps-and-discounts', 'Understand valuation caps and discounts', `<p>A valuation cap affects the price used for conversion under the agreement’s capitalization definition. A discount reduces the financing price used by that instrument. If both are present, read the agreement to determine how they interact; do not automatically apply one and then the other.</p><p>Consider an illustrative discount-only instrument with $100,000 eligible to convert and a 20% discount to a $2 financing price. Its conversion price is $2 × 80% = <strong>$1.60</strong>, giving <strong>62,500 shares</strong>. This assumes no cap, interest, additional adjustments, or rounding problem.</p><p>A cap is not a promise of the price someone will pay for the company at a sale. It is a term in the instrument’s conversion calculation.</p>`),
      section('distinguish-cap-bases', 'Distinguish pre-money and post-money SAFEs', `<p>Pre-money and post-money SAFE caps use different capitalization definitions. Under a straightforward cap-based post-money SAFE example, a $500,000 investment at a $10,000,000 post-money cap represents 5% before the new money in the priced round dilutes it. This is not a guaranteed final post-round percentage.</p><p>The round valuation, other terms, and pool changes can affect the result. Y Combinator publishes <a href="https://www.ycombinator.com/safe">SAFE forms and a user guide with conversion examples</a>, including cases where the estimated ownership changes. Check the exact form being modeled.</p><p>In Cap Table, set the SAFE’s valuation-cap type to match the agreement. Enter a discount as a percentage and leave the cap empty only for an uncapped instrument. A note additionally has fields for simple interest and maturity.</p>`),
      section('review-conversion-and-interest', 'Review conversion and interest explicitly', `<p>Interest can change the balance eligible to convert. For an illustrative note with $100,000 principal and 8% simple annual interest, exactly one year produces $8,000 interest. If the terms convert principal and that interest, the conversion balance is $108,000. The contract’s dates, day-count convention, and treatment of interest still need to match the calculation.</p><p>Record the signed terms, then use <a href="/docs/modeling-a-funding-round/">Round modeling</a> to review the proposed conversion certificates and ownership. Saving a model does not convert the instruments. The close-round workflow applies the reviewed financing records.</p><p>Review sale outcomes separately: the app’s exit model treats notes as debt repayments and evaluates SAFEs under its modeled exit alternatives. A financing conversion example does not establish what an instrument receives in an acquisition.</p>`),
    ],
  },
  {
    collection: 'guides', slug: 'liquidation-preferences-explained', category: 'Exit planning',
    title: 'Liquidation preferences and exit proceeds',
    description: 'See why ownership percentages differ from exit proceeds, with examples of a 1x nonparticipating preference and participating preferred stock.',
    summary: 'Compare ownership with what a holder receives in a sale.',
    related: ['modeling-an-exit', 'what-is-a-cap-table', 'safes-and-convertible-notes', 'participating-preferred-and-caps', 'exit-waterfall-step-by-step'],
    sections: [
      section('ownership-and-payment-rights', 'Ownership and payment rights are separate', `<p>A liquidation preference gives a class of stock a payment priority over another class in a covered liquidation event. Cooley’s <a href="https://www.cooleygo.com/glossary/liquidation-preference/">liquidation preference definition</a> explains this ordering. The applicable company and transaction documents determine which events trigger the right.</p><p>An ownership percentage describes a share-count ratio. An exit waterfall applies payment rights to the proceeds available for distribution. The two can produce different percentages for the same holder.</p>`),
      section('nonparticipating-example', 'A 1x nonparticipating example', `<p>Assume an investor put in $2,000,000 for preferred shares representing 20% on an as-converted basis. The remaining 80% is common stock. Give the preferred a 1x nonparticipating preference and a choice to convert. Exclude debt, other preferred classes, dividends, awards, fees, tax, and escrow.</p><p>Under these assumed terms, compare the $2,000,000 preference with the amount obtained by converting and taking 20% of proceeds. The holder takes one alternative, not both.</p><div class="site-table" tabindex="0" role="region" aria-label="Nonparticipating preference example"><table><caption>Illustrative payments with enough proceeds to cover the preference</caption><thead><tr><th scope="col">Sale proceeds</th><th scope="col">20% as converted</th><th scope="col">Investor receives</th><th scope="col">Common receives</th></tr></thead><tbody><tr><th scope="row">$5,000,000</th><td>$1,000,000</td><td>$2,000,000</td><td>$3,000,000</td></tr><tr><th scope="row">$10,000,000</th><td>$2,000,000</td><td>$2,000,000</td><td>$8,000,000</td></tr><tr><th scope="row">$20,000,000</th><td>$4,000,000</td><td>$4,000,000</td><td>$16,000,000</td></tr></tbody></table></div><p>The alternatives meet at $2,000,000 ÷ 20% = <strong>$10,000,000</strong>. At the $5,000,000 sale, 20% ownership yields 40% of the proceeds because of the preference.</p>`),
      section('change-the-participation-terms', 'Change the participation terms', `<p>Now change only the example’s rights: assume the investor receives its $2,000,000 preference and then participates in the remainder at 20%, with no participation cap. At a $5,000,000 sale, the remainder is $3,000,000. The investor receives $2,000,000 + 20% × $3,000,000 = <strong>$2,600,000</strong>, and common receives $2,400,000.</p><p>This is an illustration of explicitly assumed participation rights. A participation cap, a different multiple, another senior class, or a different conversion rule would require a different calculation.</p>`),
      section('account-for-shortfalls', 'Account for shortfalls and other claims', `<p>A preference is a claim on proceeds, not a guarantee that enough money exists to pay it. In the simplified nonparticipating example, a $1,000,000 distribution cannot pay a $2,000,000 preference in full. Adding creditors or senior classes can further change the amount available to a particular holder.</p><p>To use cap table software for exit planning, record the relevant rights and inspect both claims and actual modeled payments. In <a href="/docs/modeling-an-exit/">Cap Table’s exit waterfall</a>, compare several sale values, review the award assumptions, and inspect the breakeven points. The model excludes escrow, fees, and tax, so it does not calculate an individual’s final net payment.</p>`),
    ],
  },
  {
    collection: 'guides', slug: 'cap-table-maintenance-checklist', category: 'Cap table management',
    title: 'A practical cap table maintenance checklist',
    description: 'Keep a cap table accurate with a repeatable process for source documents, equity transactions, ownership reconciliation, exports, and backups.',
    summary: 'Build a repeatable review process for reliable equity records.',
    related: ['reconciling-a-cap-table', 'reading-a-historical-cap-table', 'exports-and-history'],
    sections: [
      section('establish-the-starting-record', 'Establish a traceable starting record', `<p>A useful cap table maintenance process lets another reader connect each holding to its source and reproduce the totals. Begin with a company record, a clear reporting date, and a list of the documents used to build the table.</p><ul><li>Reconcile share classes and authorizations with the governing records.</li><li>Match holder names to the people or entities in the agreements.</li><li>Match certificates, grants, and convertible instruments to their quantities, dates, and terms.</li><li>Identify plan reserves and the awards assigned to each plan.</li><li>List unresolved differences instead of filling gaps with guessed values.</li></ul><p>When moving from a spreadsheet, keep the original file and review the <a href="/docs/importing-a-cap-table/">import preview</a>. A successful import means records were accepted; reconciliation establishes whether they were the right records.</p>`),
      section('record-events-consistently', 'Use a consistent sequence for each event', `<ol><li>Identify the approved transaction and its effective date.</li><li>Check the affected holder, instrument, share class, and plan.</li><li>Record the event through the appropriate workflow.</li><li>Compare the before-and-after quantities and percentages.</li><li>Retain the supporting documents and review the saved history.</li></ol><p>For example, a partial share transfer should explain the original certificate, the receiving holder’s certificate, and the seller’s remainder. Replacing the holder’s name on the original record would not explain that chain. Similar distinctions apply to grants and their later exercise certificates.</p>`),
      section('review-before-sharing', 'Review before sharing a cap table', `<p>Check the company, reporting date, ownership basis, and treatment of the unallocated reserve. Then reconcile shares by holder and class. Review options and RSUs separately from issued shares, and check whether convertible instruments are still open or have converted.</p><p>Investigate unexpected changes in percentages. They can come from an issuance, a pool change, or a different denominator, even when a holder’s own quantity is unchanged. Conversely, a stock split can change quantities without changing proportional ownership.</p><p>Keep the exported report alongside a note describing what it represents. A stakeholder statement and a full company cap table have different scopes; choose the report the recipient needs.</p>`),
      section('use-software-deliberately', 'Use software to support the review', `<p>Whether you use a spreadsheet or cap table software, calculations depend on complete inputs. Cap Table provides CSV imports, ownership views, equity-plan tracking, financing models, and history. Those tools help organize and review records; they do not supply missing agreements or approve an issuance.</p><p>A practical way to evaluate a workflow is to use the sample company, record a representative event, inspect the resulting report, and export a backup. Check that you can explain the result and retrieve the underlying data.</p><p>Save a fresh company backup before a major import or restructuring and retain document attachments separately. Use <a href="/docs/exports-and-history/">Exports, backups, and history</a> to distinguish a readable report, a restorable company file, and the transaction trail.</p>`),
    ],
  },
];

// Keep collection and category order consistent across hubs and article navigation.
const allArticles = [...existingArticles, ...productDocs, ...workflowDocs, ...financingDocs,
  ...equityGuides, ...workedGuides, ...financingGuides, ...equityReportingGuides];
export const articles = Object.entries(collections).flatMap(([key, collection]) =>
  collection.categories.flatMap(category => allArticles.filter(a => a.collection === key && a.category === category)));
export function articlePath(article) { return `/${article.collection}/${article.slug}/`; }
